mapper.select:
SELECT l.id AS listing_id, l.store_id, l.seller_sku, l.fulfillment, s.warehouse_id, s.platform_warehouse_id
FROM ecom_listing l
JOIN ecom_store s ON s.id = l.store_id
WHERE l.status = 'ACTIVE' AND s.status = 1 AND l.id > #{afterId}
AND l.store_id = #{storeId}

    AND l.id IN #{id}

ORDER BY l.id
LIMIT #{limit}

SELECT st.material_id AS "materialId", st.warehouse_id AS "warehouseId", SUM(st.qty - st.frozen_qty) AS "qty"
FROM wms_stock st
WHERE st.material_id IN #{id}
  AND st.warehouse_id IN #{id}
GROUP BY st.material_id, st.warehouse_id

SELECT f.material_id, f.create_time AS in_time, f.qty
FROM wms_stock_flow f
WHERE f.material_id IN #{id}
  AND f.qty > 0 AND f.biz_type <> 'TRANSFER' AND f.create_time >= #{since}
ORDER BY f.material_id, f.create_time DESC, f.id DESC

SELECT ss.listing_id, l.store_id, s.name AS store_name, l.seller_sku, l.title, l.fulfillment, m.code AS material_code, m.name AS material_name, COUNT(*) AS snapshot_days, SUM(CASE WHEN ss.sellable_qty <= 0 THEN 1 ELSE 0 END) AS stockout_days, MAX(CASE WHEN ss.sellable_qty <= 0 THEN ss.snapshot_date END) AS last_stockout_date FROM ecom_stock_snapshot ss JOIN ecom_listing l ON l.id = ss.listing_id JOIN ecom_store s ON s.id = l.store_id LEFT JOIN wms_material m ON m.id = l.material_id WHERE ss.snapshot_date >= #{beginDate} AND ss.snapshot_date <= #{endDate} AND ss.store_id = #{storeId}
AND ss.listing_id IN #{id}
AND (l.seller_sku LIKE CONCAT('%', #{keyword}, '%') OR l.title LIKE CONCAT('%', #{keyword}, '%') OR m.code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY ss.listing_id, l.store_id, s.name, l.seller_sku, l.title, l.fulfillment, m.code, m.name

SELECT o.store_id, oi.seller_sku, CAST(o.order_time AS DATE) AS sale_day, COUNT(DISTINCT o.id) AS orders, SUM(oi.qty) AS qty,
       SUM( * o.exchange_rate) AS amount
FROM ecom_order_item oi
JOIN ecom_order o ON o.id = oi.order_id
WHERE o.status <> 'CANCELLED' AND o.order_time >= #{begin} AND o.order_time < #{end}
  AND o.store_id IN #{id}
  AND oi.seller_sku IN #{s}
GROUP BY o.store_id, oi.seller_sku, CAST(o.order_time AS DATE)
